// @ts-nocheck
"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { mergeRegister } from "@lexical/utils";
import {
  $getSelection,
  $isRangeSelection,
  COMMAND_PRIORITY_LOW,
  SELECTION_CHANGE_COMMAND,
} from "lexical";
import { useCallback, useEffect, useRef, useState } from "react";

interface Position {
  top: number;
  left: number;
  opacity: number;
}

interface UseFloatingToolbarReturn {
  toolbarRef: React.RefObject<HTMLDivElement | null>;
  isVisible: boolean;
  position: Position;
  activeFormats: Set<string>;
  selectedText: string;
}

const FORMATS = [
  "bold",
  "italic",
  "underline",
  "code",
  "strikethrough",
  "superscript",
  "subscript",
] as const;

export function useFloatingToolbar(
  anchorElem: HTMLElement | undefined = typeof document !== "undefined" ? document.body : undefined,
): UseFloatingToolbarReturn {
  const [editor] = useLexicalComposerContext();
  const toolbarRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout>(null);
  const rafRef = useRef<number | null>(null);

  const [activeFormats, setActiveFormats] = useState<Set<string>>(new Set());
  const [isVisible, setIsVisible] = useState(false);
  const [selectedText, setSelectedText] = useState("");
  const [position, setPosition] = useState<Position>({
    top: -1000,
    left: -1000,
    opacity: 0,
  });

  const calculatePosition = useCallback(
    (rect: DOMRect): Position => {
      const toolbar = toolbarRef.current;
      if (!toolbar) return { top: -1000, left: -1000, opacity: 0 };

      if (!toolbar || !anchorElem) return { top: -1000, left: -1000, opacity: 0 };

      const toolbarRect = toolbar.getBoundingClientRect();
      const anchorRect = anchorElem.getBoundingClientRect();

      let top = rect.top - anchorRect.top + anchorElem.scrollTop - toolbarRect.height - 10;
      let left =
        rect.left -
        anchorRect.left +
        anchorElem.scrollLeft +
        rect.width / 2 -
        toolbarRect.width / 2;

      if (left < 10) {
        left = 10;
      } else if (left + toolbarRect.width > anchorRect.width - 10) {
        left = anchorRect.width - toolbarRect.width - 10;
      }

      if (top < anchorElem.scrollTop + 10) {
        top = rect.bottom - anchorRect.top + anchorElem.scrollTop + 10;
      }

      return { top, left, opacity: 1 };
    },
    [anchorElem],
  );

  const updateToolbar = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }

    editor.read(() => {
      const selection = $getSelection();

      if (
        $isRangeSelection(selection) &&
        !selection.isCollapsed() &&
        selection.getTextContent().trim() !== ""
      ) {
        const nativeSelection = window.getSelection();
        if (!nativeSelection || nativeSelection.rangeCount === 0) {
          setIsVisible(false);
          return;
        }

        const domRange = nativeSelection.getRangeAt(0);
        const rect = domRange.getBoundingClientRect();
        const text = selection.getTextContent().trim();

        if (text.length < 1) {
          setIsVisible(false);
          return;
        }

        setSelectedText(text);

        const formats = new Set<string>();
        FORMATS.forEach((format) => {
          if (selection.hasFormat(format)) {
            formats.add(format);
          }
        });

        setActiveFormats(formats);
        setIsVisible(true);

        rafRef.current = requestAnimationFrame(() => {
          const newPosition = calculatePosition(rect);
          setPosition((prev) => {
            if (
              Math.abs(prev.top - newPosition.top) > 1 ||
              Math.abs(prev.left - newPosition.left) > 1
            ) {
              return newPosition;
            }
            return prev;
          });
        });
      } else {
        timeoutRef.current = setTimeout(() => {
          setIsVisible(false);
          setPosition((prev) => ({ ...prev, opacity: 0 }));
        }, 40);
      }
    });
  }, [editor, calculatePosition]);

  const scheduleUpdateToolbar = useCallback(() => {
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
    }

    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = null;
      updateToolbar();
    });
  }, [updateToolbar]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node;
      const editorRoot = editor.getRootElement();

      if (
        isVisible &&
        toolbarRef.current &&
        !toolbarRef.current.contains(target) &&
        !editorRoot?.contains(target)
      ) {
        setIsVisible(false);
      }
    };

    const handleScroll = () => {
      if (isVisible) {
        scheduleUpdateToolbar();
      }
    };

    const handleSelectionChange = () => {
      scheduleUpdateToolbar();
    };

    const handleResize = () => {
      if (isVisible) {
        rafRef.current = requestAnimationFrame(() => {
          const nativeSelection = window.getSelection();
          if (nativeSelection && nativeSelection.rangeCount > 0) {
            const domRange = nativeSelection.getRangeAt(0);
            const rect = domRange.getBoundingClientRect();
            const newPosition = calculatePosition(rect);
            setPosition((prev) => {
              if (
                Math.abs(prev.top - newPosition.top) > 1 ||
                Math.abs(prev.left - newPosition.left) > 1
              ) {
                return newPosition;
              }
              return prev;
            });
          }
        });
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("selectionchange", handleSelectionChange);
    window.addEventListener("scroll", handleScroll, { passive: true });
    window.addEventListener("resize", handleResize, { passive: true });

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("selectionchange", handleSelectionChange);
      window.removeEventListener("scroll", handleScroll);
      window.removeEventListener("resize", handleResize);
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [editor, isVisible, scheduleUpdateToolbar, calculatePosition]);

  useEffect(() => {
    return mergeRegister(
      editor.registerUpdateListener(({ editorState }) => {
        editorState.read(updateToolbar);
      }),
      editor.registerCommand(
        SELECTION_CHANGE_COMMAND,
        () => {
          scheduleUpdateToolbar();
          return false;
        },
        COMMAND_PRIORITY_LOW,
      ),
    );
  }, [editor, scheduleUpdateToolbar, updateToolbar]);

  return {
    toolbarRef,
    isVisible,
    position,
    activeFormats,
    selectedText,
  };
}

