"use client";

import type { ExcalidrawInitialElements } from "../../components/excalidraw-modal";
import type { AppState, BinaryFiles } from "@excalidraw/excalidraw/types";
import type { NodeKey } from "lexical";
import type { JSX } from "react";

import { exportToBlob } from "@excalidraw/excalidraw";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { mergeRegister } from "@lexical/utils";
import { $getNodeByKey, CLICK_COMMAND, COMMAND_PRIORITY_LOW, isDOMNode } from "lexical";
import { useCallback, useEffect, useMemo, useRef, useState, lazy, Suspense } from "react";
import { Download, Pencil } from "lucide-react";

const ExcalidrawModal = lazy(() => import("../../components/excalidraw-modal"));
import ImageResizer from "../../components/image-resizer";
import { $isExcalidrawNode } from ".";
import ExcalidrawImage from "./excalidraw-image";
import { Button } from "@/components/ui/button";

export default function ExcalidrawComponent({
  nodeKey,
  data,
  width,
  height,
}: {
  data: string;
  nodeKey: NodeKey;
  width: "inherit" | number;
  height: "inherit" | number;
}): JSX.Element {
  const [editor] = useLexicalComposerContext();
  const isEditable = useLexicalEditable();
  const [isModalOpen, setModalOpen] = useState<boolean>(data === "[]" && editor.isEditable());
  const imageContainerRef = useRef<HTMLDivElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);
  const captionButtonRef = useRef<HTMLButtonElement | null>(null);
  const [isSelected, setSelected, clearSelection] = useLexicalNodeSelection(nodeKey);
  const [isResizing, setIsResizing] = useState<boolean>(false);

  useEffect(() => {
    if (!isEditable) {
      if (isSelected) {
        clearSelection();
      }
      return;
    }
    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event: MouseEvent) => {
          const buttonElem = buttonRef.current;
          const eventTarget = event.target;

          if (isResizing) {
            return true;
          }

          if (buttonElem !== null && isDOMNode(eventTarget) && buttonElem.contains(eventTarget)) {
            if (!event.shiftKey) {
              clearSelection();
            }
            setSelected(!isSelected);
            if (event.detail > 1) {
              setModalOpen(true);
            }
            return true;
          }

          return false;
        },
        COMMAND_PRIORITY_LOW,
      ),
    );
  }, [clearSelection, editor, isSelected, isResizing, setSelected, isEditable]);

  const deleteNode = useCallback(() => {
    setModalOpen(false);
    return editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if (node) {
        node.remove();
      }
    });
  }, [editor, nodeKey]);

  const setData = (els: ExcalidrawInitialElements, aps: Partial<AppState>, fls: BinaryFiles) => {
    return editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if ($isExcalidrawNode(node)) {
        if ((els && els.length > 0) || Object.keys(fls).length > 0) {
          node.setData(
            JSON.stringify({
              appState: aps,
              elements: els,
              files: fls,
            }),
          );
        } else {
          node.remove();
        }
      }
    });
  };

  const onResizeStart = () => {
    setIsResizing(true);
  };

  const onResizeEnd = (nextWidth: "inherit" | number, nextHeight: "inherit" | number) => {
    setTimeout(() => {
      setIsResizing(false);
    }, 200);

    editor.update(() => {
      const node = $getNodeByKey(nodeKey);

      if ($isExcalidrawNode(node)) {
        node.setWidth(nextWidth);
        node.setHeight(nextHeight);
      }
    });
  };

  const openModal = useCallback(() => {
    setModalOpen(true);
  }, []);

  const { elements = [], files = {}, appState = {} } = useMemo(() => JSON.parse(data), [data]);

  const closeModal = useCallback(() => {
    setModalOpen(false);
    if (elements.length === 0) {
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if (node) {
          node.remove();
        }
      });
    }
  }, [editor, nodeKey, elements.length]);

  const [isHovered, setIsHovered] = useState(false);
  const handleDownload = useCallback(async () => {
    const nonDeletedElements = elements.filter((el: { isDeleted?: boolean }) => !el.isDeleted);
    if (nonDeletedElements.length === 0) return;

    try {
      const blob = await exportToBlob({
        elements: nonDeletedElements,
        files,
        appState: {
          ...appState,
          exportBackground: true,
          viewBackgroundColor: appState.viewBackgroundColor || "#ffffff",
        },
        mimeType: "image/png",
      });

      console.log("export blob:", { type: blob.type, size: blob.size });

      const filename = `excalidraw-${Date.now()}.png`;

      const url = URL.createObjectURL(blob);

      const a = document.createElement("a");
      a.href = url;
      a.download = filename;

      document.body.appendChild(a);
      a.click();

      setTimeout(() => {
        URL.revokeObjectURL(url);
        a.remove();
      }, 1000);
    } catch (error) {
      console.error("Failed to export Excalidraw drawing:", error);
    }
  }, [elements, files, appState]);

  return (
    <>
      {isEditable && isModalOpen && (
        <Suspense fallback={null}>
          <ExcalidrawModal
            initialElements={elements}
            initialFiles={files}
            initialAppState={appState}
            isShown={isModalOpen}
            onDelete={deleteNode}
            onClose={closeModal}
            onSave={(els, aps, fls) => {
              setData(els, aps, fls);
              setModalOpen(false);
            }}
            closeOnClickOutside={false}
          />
        </Suspense>
      )}
      {elements.length > 0 && (
        <button
          ref={buttonRef}
          className={`relative ${isSelected ? "bg-secondary" : ""}`}
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
        >
          <ExcalidrawImage
            imageContainerRef={imageContainerRef}
            className="image"
            elements={elements}
            files={files}
            appState={appState}
            width={width}
            height={height}
          />

          {isHovered && isEditable && (
            <div className="absolute top-3 end-3 flex gap-2">
              <Button
                type="button"
                variant={"outline"}
                onClick={(e) => {
                  e.stopPropagation();
                  openModal();
                }}
                title="Edit drawing"
              >
                <Pencil className="size-4" />
              </Button>
              <Button
                type="button"
                variant={"outline"}
                onClick={(e) => {
                  e.stopPropagation();
                  void handleDownload();
                }}
                title="Download as PNG"
              >
                <Download className="size-4" />
              </Button>
            </div>
          )}

          {isSelected && isEditable && (
            <div
              className="image-edit-button"
              role="button"
              tabIndex={0}
              onMouseDown={(event) => event.preventDefault()}
              onClick={openModal}
            />
          )}
          {(isSelected || isResizing) && isEditable && (
            <ImageResizer
              buttonRef={captionButtonRef}
              showCaption={true}
              setShowCaption={() => null}
              imageRef={imageContainerRef}
              editor={editor}
              onResizeStart={onResizeStart}
              onResizeEnd={onResizeEnd}
              captionsEnabled={true}
            />
          )}
        </button>
      )}
    </>
  );
}

