function sanitizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    if (parsed.protocol === "javascript:") return "about:blank";
    return url;
  } catch {
    if (!url.startsWith("http://") && !url.startsWith("https://") && !url.startsWith("mailto:")) {
      return `https://${url}`;
    }
    return url;
  }
}

