          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem onClick={() => modifyTable("add-row-start")}>
            Add Row Above
          </DropdownMenuItem>
          <DropdownMenuItem onClick={() => modifyTable("add-row-end")}>
